 11	class hashMap {
 12	    private static final int DEFAULT_CAPACITY = 20;
 13	    private static final int EMPTY_RESULT = -1;
 14	    private static final double MAX_LOAD_FACTOR = 0.5;
 15	
 16	    hashNode[] arr;
 17	    int capacity;
 18	    int size;
 19	    final hashNode dummy;
 20	
 21	    public hashMap() {
 22	        capacity = DEFAULT_CAPACITY;
 23	        size = 0;
 24	        arr = new hashNode[capacity];
 25	        dummy = new hashNode(EMPTY_RESULT, EMPTY_RESULT);
 26	    }
 27	
 28	    private int hashCode(int key) {
 29	        return Math.floorMod(key, capacity);
 30	    }
 31	
 32	    private int nextIndex(int index) {
 33	        return (index + 1) % capacity;
 34	    }
 35	
 36	    private boolean isTombstone(hashNode node) {
 37	        return node != null && node.key == dummy.key;
 38	    }
 39	
 40	    private int probe(int key, boolean stopAtEmpty) {
 41	        int hashIndex = hashCode(key);
 42	        int firstTombstone = EMPTY_RESULT;
 43	        int probes = 0;
 44	
 45	        while (probes < capacity) {
 46	            hashNode current = arr[hashIndex];
 47	            if (current == null) {
 48	                if (stopAtEmpty) {
 49	                    return EMPTY_RESULT;
 50	                }
 51	                return firstTombstone != EMPTY_RESULT ? firstTombstone : hashIndex;
 52	            }
 53	            if (current.key == key) {
 54	                return hashIndex;
 55	            }
 56	            if (isTombstone(current) && firstTombstone == EMPTY_RESULT) {
 57	                firstTombstone = hashIndex;
 58	            }
 59	            hashIndex = nextIndex(hashIndex);
 60	            probes++;
 61	        }
 62	
 63	        return stopAtEmpty ? EMPTY_RESULT : firstTombstone;
 64	    }
 65	
 66	    private void resizeIfNeeded() {
 67	        if (size < capacity * MAX_LOAD_FACTOR) {
 68	            return;
 69	        }
 70	
 71	        hashNode[] previous = arr;
 72	        capacity *= 2;
 73	        arr = new hashNode[capacity];
 74	        size = 0;
 75	
 76	        for (hashNode node : previous) {
 77	            if (node != null && !isTombstone(node)) {
 78	                placeNode(node.key, node.value);
 79	            }
 80	        }
 81	    }
 82	
 83	    private void placeNode(int key, int value) {
 84	        int index = probe(key, false);
 85	        if (index == EMPTY_RESULT) {
 86	            return;
 87	        }
 88	
 89	        if (arr[index] == null || arr[index].key == dummy.key) {
 90	            size++;
 91	        }
 92	        arr[index] = new hashNode(key, value);
 93	    }
 94	
 95	    void insertNode(int key, int value) {
 96	        resizeIfNeeded();
 97	        placeNode(key, value);
 98	    }
 99	
100	    private int findExistingIndex(int key) {
101	        return probe(key, true);
102	    }
103	
104	    int deleteNode(int key) {
105	        int hashIndex = findExistingIndex(key);
106	        if (hashIndex == EMPTY_RESULT) {
107	            return EMPTY_RESULT;
108	        }
109	
110	        int deletedValue = arr[hashIndex].value;
111	        arr[hashIndex] = dummy;
112	        size--;
113	        return deletedValue;
114	    }
115	
116	    int get(int key) {
117	        int hashIndex = findExistingIndex(key);
118	        if (hashIndex == EMPTY_RESULT) {
119	            return EMPTY_RESULT;
120	        }
121	
122	        return arr[hashIndex].value;
123	    }
124	
125	    int sizeofMap() {
126	        return size;
127	    }
128	
129	    boolean isEmpty() {
130	        return size == 0;
131	    }
132	
133	    void display() {
134	        for (int i = 0; i < capacity; i++) {
135	            if (arr[i] != null && !isTombstone(arr[i])) {
136	                System.out.println(arr[i].key +
137	                " " + arr[i].value);
138	            }
139	        }
140	    }
141	
142	    public static void main(String[] args) {
143	        hashMap h = new hashMap();
144	        h.insertNode(1, 1);
145	        h.insertNode(2, 2);
146	        h.insertNode(2, 3);
147	        h.display();
148	        System.out.println(h.sizeofMap());
149	        System.out.println(h.deleteNode(2));
150	        System.out.println(h.sizeofMap());
151	        System.out.println(h.isEmpty());
152	        System.out.println(h.get(2));
153	    }
154	}

